// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        bool ok;
        try c.withdrawAll(actor) { ok = true; } catch { ok = false; }
        assertTrue(!ok || balBefore == address(c).balance);
    }
}
